from __future__ import annotations

import sys
from pathlib import Path

import polars as pl
import pytest
from ds.data import init_db

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "experimental" / "reflex-kernel"
sys.path.insert(0, str(APP_DIR))

from reflex_kernel.db_console import MAX_HISTORY, DbConsole  # noqa: E402
from reflex_kernel.render import Ui, apply_event, to_view  # noqa: E402
from reflex_kernel.widgets import widget_of  # noqa: E402


@pytest.fixture
def console() -> DbConsole:
    return DbConsole(init_db())


def test_run_gives_a_new_console_with_the_result(console: DbConsole):
    ran = console.run("  select id, name from char order by id limit 3;  ")
    assert ran is not console
    assert console.df is None
    assert (ran.df.shape, ran.df.columns) == ((3, 2), ["id", "name"])
    assert ran.sql == "select id, name from char order by id limit 3"
    assert ran.history == (ran.sql,)
    assert ran.timing.endswith((" ms", " s"))


def test_a_bad_query_raises_and_leaves_the_console(console: DbConsole):
    ran = console.run("select * from char")
    with pytest.raises(pl.exceptions.PolarsError):
        ran.run("select nope from char")
    assert ran.sql == "select * from char"
    assert ran.history == ("select * from char",)


def test_history_is_newest_first_without_repeats(console: DbConsole):
    for query in ["select 1", "select 2", "select 1"]:
        console = console.run(query)
    assert console.history == ("select 1", "select 2")
    for number in range(MAX_HISTORY + 5):
        console = console.run(f"select {number} as n")
    assert len(console.history) == MAX_HISTORY
    assert console.history[0] == f"select {MAX_HISTORY + 4} as n"


def test_tables_list_columns_and_see_new_tables(console: DbConsole):
    tables = {table.name: table for table in console.tables(opened=["char"])}
    assert {"char", "framedata"} <= set(tables)
    assert tables["char"].open
    assert not tables["framedata"].open
    assert {"name": "id", "dtype": "String"} in tables["char"].columns
    assert int(tables["char"].rows.replace(",", "")) > 0
    console.run("create table fast as select * from char limit 2")
    assert "fast" in [table.name for table in console.tables()]


def test_view_is_a_table_with_the_console_around_it(console: DbConsole):
    blank = to_view(console)
    assert (blank.kind, blank.summary) == ("smashdb", "not run yet")
    data = blank.data("tab:r1")
    assert (data.db_ran, data.rows, data.label) == (False, [], "SmashDb")
    assert "char" in data.db_schema
    assert "id" in data.db_schema["char"]

    ran = console.run("select id, name from char order by id")
    view, ui = to_view(ran), Ui()
    data = view.data("tab:r1", ui)
    assert data.db_ran
    assert data.db_sql == ran.sql
    assert data.db_history == [ran.sql]
    assert [column["title"] for column in data.columns] == ["id", "name"]
    assert len(data.rows) == ran.df.height
    assert data.note.endswith(ran.timing)
    # the result is a table view: sort, filter and SQL on `self` work on it
    apply_event(view, ui, "sort", 0)
    apply_event(view, ui, "sort", 0)
    apply_event(view, ui, "sql", "select id from self limit 5")
    data = view.data("tab:r1", ui)
    assert (data.sort_col, data.sort_desc, data.sql_active) == ("id", True, True)
    assert (len(data.rows), len(data.columns)) == (5, 1)


def test_console_ui_events(console: DbConsole):
    view, ui = to_view(console), Ui()
    apply_event(view, ui, "db_toggle", "char")
    assert [table.name for table in view.data("tab:r1", ui).db_tables if table.open] == ["char"]
    apply_event(view, ui, "db_toggle", "char")
    assert ui.db_open == []
    apply_event(view, ui, "db_draft", "select 1")
    assert view.data("tab:r1", ui).db_sql == "select 1"
    key = view.data("tab:r1", ui).db_key
    apply_event(view, ui, "db_pick", "select 2")
    data = view.data("tab:r1", ui)
    assert (data.db_sql, data.db_history_open) == ("select 2", False)
    assert data.db_key != key


def test_widget_is_addable_on_the_sessions_db():
    from reflex_kernel.session import Session

    session = Session()
    widget = widget_of("smashdb")
    assert widget.addable
    assert widget.form is None
    made = widget.blank(session)
    assert isinstance(made, DbConsole)
    assert made.db is session.db
    assert session.namespace["db"] is session.db


def test_save_as_names():
    from reflex_kernel.session import Session

    session = Session()
    assert session.next_free_name("q") == "q1"
    session.namespace["q1"] = 1
    assert session.next_free_name("q") == "q2"
    assert session.name_problem("top_moves") == ""
    assert session.name_problem("q1") == ""  # replaced, as in Python
    for bad in ["1x", "my name", "class", "_hidden", "db", "pl"]:
        assert session.name_problem(bad), bad
    assert session.name_problem("r1", keep="r1")  # the console itself


def test_save_as_toggle_and_suggestion(console: DbConsole):
    from reflex_kernel.session import Session

    session = Session()
    session.namespace["r1"] = console.run("select id from char limit 2")
    ui = session.ui.setdefault("tab:r1", Ui())
    apply_event(session.view_at("tab:r1"), ui, "db_save_toggle", "")
    data = session.show("tab:r1")
    assert (data.db_save_open, data.db_save_name) == (True, "q1")
    apply_event(session.view_at("tab:r1"), ui, "db_save_toggle", "")
    assert not session.show("tab:r1").db_save_open
